node -e '
const fs = require("node:fs");
const files = ["admin-routes.mjs","search-api.mjs","session-store.mjs","webhook.mjs"];
const routeSrc = fs.readFileSync("input/routes.mjs","utf8");
const routeAuth = new Map([...routeSrc.matchAll(/\{\s*path:\s*"[^"]*",\s*handler:\s*"([^"]+)",\s*auth:\s*"([^"]+)"\s*\}/g)].map(m=>[m[1],m[2]]));
console.log("route_auth="+JSON.stringify([...routeAuth.entries()]));

function enclosingFunction(lines, lineIndex) {
  for (let cursor = lineIndex; cursor >= 0; cursor -= 1) {
    if (cursor < lineIndex && /^\}/.test(lines[cursor])) return null;
    const decl = /^(?:export\s+)?(?:async\s+)?function\s+([A-Za-z_$][\w$]*)/.exec(lines[cursor]);
    if (decl) return decl[1];
  }
  return null;
}

const LADDER = ["low","medium","high","critical"];
function raise(sev){ return LADDER[Math.min(LADDER.indexOf(sev)+1, LADDER.length-1)]; }

for (const name of files) {
  const lines = fs.readFileSync("input/"+name,"utf8").split("\n");
  lines.forEach((line, idx) => {
    if (/\bdb\.query\(\s*`[^`]*\$\{/.test(line)) {
      const owner = enclosingFunction(lines, idx);
      const auth = owner ? routeAuth.get(owner) : undefined;
      let sev = "high";
      if (auth === "public") sev = raise(sev);
      console.log("SQLI file=input/"+name+" line="+(idx+1)+" owner="+owner+" auth="+auth+" severity="+sev+" text="+JSON.stringify(line.trim()));
    }
  });
}
'

